import sys, pathlib
s = pathlib.Path(sys.argv[1])
adb = s / "src/heaps-leftist.adb"
t = adb.read_text()

# --- declarations: ghost snapshots -------------------------------------
old = """   is
      Top   : Index;
      Other : Index;
      Rest  : Extended_Index;
      Sub   : Extended_Index;
      Swap  : Extended_Index;
   begin"""
new = """   is
      Top   : Index;
      Other : Index;
      Rest  : Extended_Index;
      Sub   : Extended_Index;
      Swap  : Extended_Index;

      H0 : constant Heap := H with Ghost;
      --  The state on entry, which the model postcondition speaks about
   begin"""
assert old in t
t = t.replace(old, new, 1)

# --- empty-operand case ------------------------------------------------
old = """      if A = 0 or else B = 0 then
         R := (if A = 0 then B else A);

         pragma Assert (Well_Linked (H));
         return;
      end if;"""
new = """      if A = 0 or else B = 0 then
         R := (if A = 0 then B else A);

         pragma Assert (Well_Linked (H));

         --  One operand is the empty tree, so the sum is the other one.

         if A = 0 then
            Key_Multisets.Lemma_Sym_Sum
              (Tree_Model (H, A), Tree_Model (H, B));
         end if;
         Models.Lemma_Sum_Empty (Tree_Model (H, R));

         return;
      end if;"""
assert old in t
t = t.replace(old, new, 1)

# --- after the detach: frame the three trees ---------------------------
old = """      Merge (H, Rest, Other, Sub);

      --  Top was a tree of its own across the call, so the merge left it
      --  alone, and what it says about its left subtree still holds."""
new = """      --  Detaching the right subtree changed the children of Top and the
      --  parent of Rest. Tree_Model never reads a Parent field, so the only
      --  visible change is at Top -- and Top is in none of the three trees
      --  the recursive call is about: its subtree is strictly larger than
      --  either of its own former children's, and Other is a root of another
      --  tree entirely.

      Frame_The_Detach :
      declare
         H1   : constant Heap := H with Ghost;
         Left : constant Extended_Index := H.Links (Top).Left with Ghost;
      begin
         for Y in 1 .. H.Count loop
            if Y /= Top then
               null;
            elsif Left /= 0 and then Reaches (H0, Left, Y) then
               Lemma_Reaches_Size (H0, Left, Y);
            end if;

            pragma Loop_Invariant
              (for all Z in 1 .. Y =>
                 (if Left /= 0 and then Reaches (H0, Left, Z)
                  then Z /= Top));
         end loop;

         for Y in 1 .. H.Count loop
            if Y = Top and then Rest /= 0 and then Reaches (H0, Rest, Y) then
               Lemma_Reaches_Size (H0, Rest, Y);
            end if;

            pragma Loop_Invariant
              (for all Z in 1 .. Y =>
                 (if Rest /= 0 and then Reaches (H0, Rest, Z)
                  then Z /= Top));
         end loop;

         pragma Assert (not Reaches (H0, Other, Top));

         if Left /= 0 then
            Lemma_Model_Frame (H0, H1, Left);
         end if;
         if Rest /= 0 then
            Lemma_Model_Frame (H0, H1, Rest);
         end if;
         Lemma_Model_Frame (H0, H1, Other);

         --  Top with its right subtree cut off holds its left subtree plus
         --  its own key.

         Models.Lemma_Sum_Empty (Tree_Model (H1, Left));
         pragma Assert
           (Tree_Model (H1, Top)
            = Key_Multisets.Add (Tree_Model (H0, Left), H0.Keys (Top)));
      end Frame_The_Detach;

      Merge (H, Rest, Other, Sub);

      --  Top was a tree of its own across the call, so the merge left it
      --  alone, and what it says about its left subtree still holds."""
assert old in t
t = t.replace(old, new, 1)
adb.write_text(t)
print("ok", len(t.splitlines()))
