with SPARK.Containers.Functional.Multisets;
package GP with SPARK_Mode is
   type Key_Type is new Integer with Default_Value => 0;
   package KM is new SPARK.Containers.Functional.Multisets (Key_Type, "=");

   subtype Idx is Natural range 0 .. 1024;
   type Link is record
      Left, Right, Size : Idx := 0;
   end record;
   type Link_Array is array (1 .. 1024) of Link;
   type Key_Array  is array (1 .. 1024) of Key_Type;

   type Model_Array is array (1 .. 1024) of KM.Multiset with Ghost;
   --  The cached per-tree models, kept outside the heap so that they can be
   --  a ghost parameter and so cost nothing at run time.

   type Heap is record
      Count : Idx := 0;
      Keys  : Key_Array;
      Links : Link_Array;
   end record;

   function Sub_Of (M : Model_Array; I : Idx) return KM.Multiset is
     (if I = 0 then KM.Empty_Multiset else M (I)) with Ghost;

   function Cached (H : Heap; M : Model_Array) return Boolean is
     (for all I in 1 .. H.Count =>
        M (I) = KM.Add (KM.Sum (Sub_Of (M, H.Links (I).Left),
                                Sub_Of (M, H.Links (I).Right)),
                        H.Keys (I)))
     with Ghost;
   --  One clause about one node and its two children: no recursion, no
   --  reachability, and a third tree's model is a single field of its root.

   procedure Insert (H : in out Heap; M : in out Model_Array; K : Key_Type)
     with Ghost_Predicate => True,
          Pre  => H.Count < 1024 and then Cached (H, M),
          Post => Cached (H, M);
end GP;
