   procedure Lemma_Model_Frame (H1, H2 : Heap; I : Extended_Index) is
   begin
      if I = 0 then
         return;
      end if;

      pragma Assert (Reaches (H1, I, I));

      declare
         Left  : constant Extended_Index := H1.Links (I).Left;
         Right : constant Extended_Index := H1.Links (I).Right;
      begin
         --  Carry this call's hypothesis one step down, once per child, and
         --  recurse. The two branches are spelled out rather than factored
         --  into a nested procedure: a nested one would be mutually recursive
         --  with this lemma, and SPARK asks mutually recursive subprograms for
         --  a common variant, which they do not have.

         if Left /= 0 then
            for Y in 1 .. H1.Count loop
               if Reaches (H1, Left, Y) then
                  Lemma_Reaches_Child (H1, I, Left, Y);
               end if;

               pragma Loop_Invariant
                 (for all Z in 1 .. Y =>
                    (if Reaches (H1, Left, Z)
                     then H2.Keys (Z) = H1.Keys (Z)
                          and then H2.Links (Z).Left = H1.Links (Z).Left
                          and then H2.Links (Z).Right = H1.Links (Z).Right));
            end loop;

            Lemma_Model_Frame (H1, H2, Left);
         end if;

         if Right /= 0 then
            for Y in 1 .. H1.Count loop
               if Reaches (H1, Right, Y) then
                  Lemma_Reaches_Child (H1, I, Right, Y);
               end if;

               pragma Loop_Invariant
                 (for all Z in 1 .. Y =>
                    (if Reaches (H1, Right, Z)
                     then H2.Keys (Z) = H1.Keys (Z)
                          and then H2.Links (Z).Left = H1.Links (Z).Left
                          and then H2.Links (Z).Right = H1.Links (Z).Right));
            end loop;

            Lemma_Model_Frame (H1, H2, Right);
         end if;

         --  Both subtrees have the same model in the two states, and I itself
         --  holds the same key and the same two children, so the node above
         --  them builds the same multiset.

         pragma Assert (Tree_Model (H2, Left) = Tree_Model (H1, Left));
         pragma Assert (Tree_Model (H2, Right) = Tree_Model (H1, Right));

         Models.Lemma_Sum_Congruent
           (Tree_Model (H2, Left), Tree_Model (H1, Left),
            Tree_Model (H2, Right));
         Models.Lemma_Sum_Congruent
           (Tree_Model (H2, Right), Tree_Model (H1, Right),
            Tree_Model (H1, Left));
         Models.Lemma_Add_Congruent
           (Key_Multisets.Sum (Tree_Model (H2, Left), Tree_Model (H2, Right)),
            Key_Multisets.Sum (Tree_Model (H1, Left), Tree_Model (H1, Right)),
            H1.Keys (I));
      end;
   end Lemma_Model_Frame;
