with SPARK.Containers.Functional.Multisets;
package AT_ with SPARK_Mode is
   type Key_Type is new Integer with Default_Value => 0;
   package KM is new SPARK.Containers.Functional.Multisets (Key_Type, "=");
   use type KM.Multiset;

   subtype Idx is Natural range 0 .. 1024;

   type Link is record
      Left, Right, Parent, Size, Dist : Idx := 0;
   end record;

   function Valid return Boolean with Ghost;
   function Model (T : Idx) return KM.Multiset with Ghost;

   procedure Insert (T : in out Idx; K : Key_Type)
     with Pre  => Valid,
          Post => Valid and then Model (T) = KM.Add (Model (T)'Old, K);

private
   Links : array (1 .. 1024) of Link;
   Keys  : array (1 .. 1024) of Key_Type;
   Count : Idx := 0;

   type Model_Array is array (1 .. 1024) of KM.Multiset with Ghost;
   Sub : Model_Array with Ghost;
   --  The cached model of the tree rooted at each node

   function Sub_Of (I : Idx) return KM.Multiset is
     (if I = 0 then KM.Empty_Multiset else Sub (I))
     with Ghost;

   function Model (T : Idx) return KM.Multiset is (Sub_Of (T));

   function Valid return Boolean is
     (for all I in 1 .. Count =>
        Links (I).Size = 1 + (if Links (I).Left = 0 then 0
                              else Links (Links (I).Left).Size)
                           + (if Links (I).Right = 0 then 0
                              else Links (Links (I).Right).Size)
        and then Sub (I) = KM.Add (KM.Sum (Sub_Of (Links (I).Left),
                                           Sub_Of (Links (I).Right)),
                                   Keys (I)));
   --  One clause per node about that node and its two children: no recursion,
   --  and a tree's model is a single field of its root.
end AT_;
