--
--  SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
--

pragma Assertion_Policy (Ghost          => Ignore,
                         Pre            => Ignore,
                         Post           => Ignore,
                         Assert         => Ignore,
                         Loop_Invariant => Ignore);

with Heaps.Models;

package body Heaps.Leftist_Arena with SPARK_Mode is

   package KM renames Key_Multisets;

   --------------------------
   -- Allocation          --
   --------------------------

   procedure Allocate (I : out Index)
     with Pre  => Valid and then Free_Count >= 1,
          Post => Valid
                  and then In_Use (I)
                  and then Free_Count = Free_Count'Old - 1
                  and then Keys = Keys'Old
                  and then Links (I).Left = 0
                  and then Links (I).Right = 0
                  and then Links (I).Parent = 0
                  and then Links (I).Size = 1
                  and then Links (I).Dist = 1
                  and then KM.Is_Empty (Sub (I))

                  --  Every node that was in use is untouched, model included

                  and then (for all X in 1 .. Capacity =>
                              (if Chain_Pos'Old (X) = 0
                               then X /= I
                                    and then In_Use (X)
                                    and then Links (X) = Links'Old (X)
                                    and then Sub (X) = Sub'Old (X)));
   --  Take the head of the free chain and hand it back as a one-node tree with
   --  an empty subtree model, ready for a key to be stored in it.

   procedure Deallocate (I : Index)
     with Pre  => Valid
                  and then In_Use (I)
                  and then Links (I).Left = 0
                  and then Links (I).Right = 0
                  and then Links (I).Parent = 0
                  and then (for all X in 1 .. Capacity =>
                              (if In_Use (X) and then X /= I
                               then Links (X).Left /= I
                                    and then Links (X).Right /= I
                                    and then Links (X).Parent /= I)),
          Post => Valid
                  and then not In_Use (I)
                  and then Free_Count = Free_Count'Old + 1
                  and then Keys = Keys'Old
                  and then (for all X in 1 .. Capacity =>
                              (if Chain_Pos'Old (X) = 0 and then X /= I
                               then In_Use (X)
                                    and then Links (X) = Links'Old (X)
                                    and then Sub (X) = Sub'Old (X)));
   --  Push a detached node back onto the free chain. It has to be detached
   --  already -- no link anywhere may still name it -- which is what the
   --  precondition asks for.

   --------------
   -- Allocate --
   --------------

   procedure Allocate (I : out Index) is
      Head : constant Index := Free;
      Next : constant Extended_Index := Links (Head).Left;
   begin
      I := Head;

      --  The head is the only free node at the far end of the chain, so every
      --  other free node is at a position that survives the decrement.

      Free       := Next;
      Free_Count := Free_Count - 1;

      Chain_Pos (Head) := 0;
      Links (Head) :=
        (Left => 0, Right => 0, Parent => 0, Size => 1, Dist => 1);
      Sub (Head) := KM.Empty_Multiset;
   end Allocate;

   ----------------
   -- Deallocate --
   ----------------

   procedure Deallocate (I : Index) is
   begin
      Links (I).Left   := Free;
      Free_Count       := Free_Count + 1;
      Chain_Pos (I)    := Free_Count;
      Free             := I;
   end Deallocate;

   -----------
   -- Clear --
   -----------

   procedure Clear is
   begin
      --  Thread every slot onto the free chain, the last slot at the head, so
      --  that a slot's position along the chain is its own index.

      for J in 1 .. Capacity loop
         Links (J) :=
           (Left => (if J = 1 then 0 else J - 1),
            Right => 0, Parent => 0, Size => 0, Dist => 0);
         Chain_Pos (J) := J;
         Sub (J) := KM.Empty_Multiset;

         pragma Loop_Invariant
           (for all X in 1 .. J =>
              Chain_Pos (X) = X
              and then Links (X).Left = (if X = 1 then 0 else X - 1));
      end loop;

      Free       := Capacity;
      Free_Count := Capacity;
   end Clear;

   -------------
   -- Size_Of --
   -------------

   function Size_Of (T : Tree) return Extended_Index is
     (if T = 0 then 0 else Links (T).Size);

   --------------
   -- Peek_Min --
   --------------

   function Peek_Min (T : Tree) return Key_Type is (Keys (T));

   -----------
   -- Merge --
   -----------

   procedure Merge (A, B : Extended_Index; R : out Extended_Index)
     with Pre  => Valid
                  and then A <= Capacity
                  and then B <= Capacity
                  and then (if A /= 0
                            then In_Use (A) and then Links (A).Parent = 0)
                  and then (if B /= 0
                            then In_Use (B) and then Links (B).Parent = 0)
                  and then (if A /= 0 and then B /= 0 then A /= B),
          Post => Valid
                  and then Keys = Keys'Old
                  and then Chain_Pos = Chain_Pos'Old
                  and then Free = Free'Old
                  and then Free_Count = Free_Count'Old
                  and then R <= Capacity
                  and then (if A = 0 then R = B
                            elsif B = 0 then R = A
                            else R = A or else R = B)
                  and then (if R /= 0
                            then In_Use (R)
                                 and then Links (R).Parent = 0
                                 and then Links (R).Size
                                          = Size_Of_Node (A)'Old
                                            + Size_Of_Node (B)'Old)

                  --  The model of the result is the sum of the two operands'.
                  --  Because the model is cached, this is an equality between
                  --  three array elements rather than a statement about which
                  --  nodes belong to which tree.

                  and then Sub_Of (R) = Sub_Of (A)'Old + Sub_Of (B)'Old

                  --  A merge creates no root except the one it returns, and A
                  --  and B are no longer roots.

                  and then (for all X in 1 .. Capacity =>
                              (if In_Use (X)
                                  and then Links (X).Parent = 0
                                  and then X /= R
                               then Links'Old (X).Parent = 0
                                    and then X /= A
                                    and then X /= B))

                  --  And the other trees of the arena come back untouched,
                  --  their cached models included. This is the clause that
                  --  the recursive alternative could not state without a
                  --  reachability relation, and it composes through the
                  --  recursion exactly as the link-level frame does.

                  and then (for all X in 1 .. Capacity =>
                              (if Chain_Pos'Old (X) = 0
                                  and then Links'Old (X).Parent = 0
                                  and then X /= A
                                  and then X /= B
                               then Links (X) = Links'Old (X)
                                    and then Sub (X) = Sub'Old (X))),
          Subprogram_Variant =>
            (Decreases => Size_Of_Node (A) + Size_Of_Node (B));
   --  Merge the two trees rooted at A and B into one and return its root.
   --  Everything the operations do to the shape of the arena happens here.

   procedure Merge (A, B : Extended_Index; R : out Extended_Index) is
      Top   : Index;
      Other : Index;
      Rest  : Extended_Index;
      Sub_R : Extended_Index;
      Swap  : Extended_Index;
   begin
      if A = 0 or else B = 0 then
         R := (if A = 0 then B else A);

         if A = 0 then
            KM.Lemma_Sym_Sum (Sub_Of (A), Sub_Of (B));
         end if;
         Models.Lemma_Sum_Empty (Sub_Of (R));

         return;
      end if;

      --  The smaller of the two roots is the root of the result

      if Keys (A) <= Keys (B) then
         Top := A;
         Other := B;
      else
         Top := B;
         Other := A;
      end if;

      --  Detach the right subtree of Top. Doing so before the recursive call
      --  rather than after it keeps the arena a well formed forest throughout:
      --  Top is left a smaller but perfectly valid tree, and the subtree that
      --  has just left it becomes a tree of its own. The cached model of Top
      --  is brought down with its Size, by the same assignment.

      Rest := Links (Top).Right;

      if Rest /= 0 then
         Links (Rest).Parent := 0;
      end if;

      Links (Top).Right := 0;
      Links (Top).Size := 1 + Size_Of_Node (Links (Top).Left);
      Links (Top).Dist := 1;
      Sub (Top) :=
        KM.Add (KM.Sum (Sub_Of (Links (Top).Left), Sub_Of (Links (Top).Right)),
                Keys (Top));

      Merge (Rest, Other, Sub_R);

      --  Top was a tree of its own across the call, so the merge left it
      --  alone -- its links and its cached model both.

      pragma Assert (Sub_R /= 0 and then Sub_R /= Top);
      pragma Assert (Links (Sub_R).Parent = 0);
      pragma Assert (Links (Top).Left /= Sub_R);

      Links (Sub_R).Parent := Top;
      Links (Top).Right := Sub_R;

      --  Restore the leftist condition by putting the deeper subtree on the
      --  left, then say what the node has become.

      if Dist_Of (Links (Top).Left) < Dist_Of (Links (Top).Right) then
         Swap := Links (Top).Left;
         Links (Top).Left := Links (Top).Right;
         Links (Top).Right := Swap;
      end if;

      Links (Top).Size :=
        1 + Size_Of_Node (Links (Top).Left) + Size_Of_Node (Links (Top).Right);
      Links (Top).Dist := 1 + Dist_Of (Links (Top).Right);
      Sub (Top) :=
        KM.Add (KM.Sum (Sub_Of (Links (Top).Left), Sub_Of (Links (Top).Right)),
                Keys (Top));

      R := Top;
   end Merge;

   ----------
   -- Meld --
   ----------

   procedure Meld (T : in out Tree; U : in out Tree) is
      New_Root : Extended_Index;
   begin
      Merge (T, U, New_Root);
      T := New_Root;
      U := 0;
   end Meld;

   ------------
   -- Insert --
   ------------

   procedure Insert (T : in out Tree; K : Key_Type) is
      Slot     : Index;
      New_Root : Extended_Index;
      Before   : constant Tree := T;
   begin
      Allocate (Slot);
      Keys (Slot) := K;
      Sub (Slot) := KM.Add (KM.Empty_Multiset, K);

      pragma Assert (Before /= Slot);

      Merge (Before, Slot, New_Root);
      T := New_Root;

      Models.Lemma_Sum_Empty (Sub_Of (Before));
      Models.Lemma_Sum_Add (Sub_Of (Before), KM.Empty_Multiset, K);
   end Insert;

   -----------------
   -- Extract_Min --
   -----------------

   procedure Extract_Min (T : in out Tree; K : out Key_Type) is
      Gone     : constant Index := T;
      Left     : constant Extended_Index := Links (Gone).Left;
      Right    : constant Extended_Index := Links (Gone).Right;
      New_Root : Extended_Index;
   begin
      K := Keys (Gone);

      --  Cut the two subtrees loose and give the root's slot back. Without
      --  prefix compaction there is nothing else to do: no live node moves, so
      --  no cached model has to follow one.

      if Left /= 0 then
         Links (Left).Parent := 0;
      end if;

      if Right /= 0 then
         Links (Right).Parent := 0;
      end if;

      Links (Gone) := (Left => 0, Right => 0, Parent => 0, Size => 0,
                       Dist => 0);
      Sub (Gone) := KM.Empty_Multiset;

      Deallocate (Gone);

      Merge (Left, Right, New_Root);
      T := New_Root;
   end Extract_Min;

end Heaps.Leftist_Arena;

